# Last step. Hash every input and output. Do not edit this file after it runs.
# Usage: python -I work/scripts/write_manifest_k1.py
import hashlib
import json
import subprocess
from pathlib import Path

ROOT = Path('.').resolve()
RESEARCH = [
    'TASK.md',
    'brief.md',
    'templates/result.md',
    'ref/tasks/T3j-afon-acceptance-assertions/brief.md',
    'ref/tasks/T3j-afon-acceptance-assertions/decision.md',
    'ref/analysis/button-af/readiness/t3-afon-zone-row/design/T3i-design.md',
    'ref/analysis/button-af/readiness/t3-afon-zone-row/README.md',
    'ref/analysis/button-af/AFON-MENU-RESEARCH.md',
    'ref/AF-PROFILE-PROTOTYPE.md',
    'ref/scripts/om_emu_af_edge_overlay.py',
    'ref/scripts/om_emu_af_live_probe.mjs',
    'ref/analysis/button-af/readiness/om-emu-af-native1/central-edge-v2.csv',
    'ref/analysis/button-af/readiness/om-emu-af-native1/central-edge-v2.json',
    'ref/analysis/button-af/readiness/task-context-placement1/live-profile-relocation-map.txt',
]


def rel(path):
    s = str(path).replace('\\', '/')
    root = str(ROOT).replace('\\', '/')
    if s.lower().startswith(root.lower() + '/'):
        s = s[len(root) + 1:]
    return s


def sha_file(path):
    data = Path(path).read_bytes()
    return hashlib.sha256(data).hexdigest(), len(data)


def add_exec(store, path, digest, nbytes, where):
    key = rel(path)
    row = store.setdefault(key, {'sha256': digest, 'bytes': nbytes, 'where': []})
    if row['sha256'] != digest or row['bytes'] != nbytes:
        row.setdefault('conflicts', []).append({'sha256': digest, 'bytes': nbytes, 'where': where})
    row['where'].append(where)


exec_hashes = {}
inventory_path = Path('work/out/import-inventory-k1.json')
if inventory_path.exists():
    inventory = json.loads(inventory_path.read_text(encoding='utf-8'))
    for item in inventory.get('modules', []) + inventory.get('resources', []):
        add_exec(exec_hashes, item['path'], item['sha256'], item['bytes'], rel(inventory_path))

for path in sorted(Path('work/out').rglob('*.jsonl')):
    for line in path.read_text(encoding='utf-8').splitlines():
        if '"helper-hashes"' not in line:
            continue
        rec = json.loads(line)
        if rec.get('step') != 'helper-hashes':
            continue
        where = rel(path) + '#helper-hashes'
        for item in rec.get('helpers', []) + rec.get('resources', []):
            add_exec(exec_hashes, item['path'], item['sha256'], item.get('bytes'), where)

for exit_path in sorted(Path('work/out/cmd').glob('*.exit'), key=lambda p: int(p.name.split('.')[0])):
    doc = json.loads(exit_path.read_text(encoding='utf-8'))
    for item in doc.get('scripts') or []:
        add_exec(exec_hashes, item['path'], item['sha256'], item.get('bytes'), rel(exit_path))

inputs = []
seen = set()
for key, rec in sorted(exec_hashes.items()):
    if key.startswith('work/'):
        continue
    later, nbytes = sha_file(key)
    inputs.append({
        'path': key,
        'sha256': rec['sha256'],
        'bytes': rec['bytes'],
        'hashed': 'execution',
        'execution_where': rec['where'],
        'later_sha256': later,
        'later_matches': later == rec['sha256'] and nbytes == rec['bytes'],
        'conflicts': rec.get('conflicts', []),
    })
    seen.add(key)
for path in RESEARCH:
    if not Path(path).exists() or rel(path) in seen:
        continue
    digest, nbytes = sha_file(path)
    inputs.append({'path': rel(path), 'sha256': digest, 'bytes': nbytes, 'hashed': 'later'})
    seen.add(rel(path))

sources = []
for path in sorted(Path('work/scripts').glob('*')):
    if not path.is_file():
        continue
    digest, nbytes = sha_file(path)
    key = rel(path)
    row = {'path': key, 'sha256': digest, 'bytes': nbytes, 'hashed': 'later'}
    if key in exec_hashes:
        rec = exec_hashes[key]
        row['hashed'] = 'execution'
        row['execution_sha256'] = rec['sha256']
        row['execution_where'] = rec['where']
        row['later_matches'] = digest == rec['sha256'] and nbytes == rec['bytes']
        row['conflicts'] = rec.get('conflicts', [])
    sources.append(row)

outputs = []
out_files = [Path('work/result.md')]
out_files.extend(p for p in Path('work/out').rglob('*') if p.is_file())
for path in sorted(out_files, key=lambda p: rel(p)):
    digest, nbytes = sha_file(path)
    outputs.append({'path': rel(path), 'sha256': digest, 'bytes': nbytes, 'hashed': 'later'})

commands = []
for exit_path in sorted(Path('work/out/cmd').glob('*.exit'), key=lambda p: int(p.name.split('.')[0])):
    doc = json.loads(exit_path.read_text(encoding='utf-8'))
    n = exit_path.name.split('.')[0]
    commands.append({
        'id': n,
        'spawn': doc.get('spawn'),
        'status': doc.get('status'),
        'start': doc.get('start'),
        'end': doc.get('end'),
        'exit_file': rel(exit_path),
        'hashed': 'later',
    })
commands.append({
    'id': '39',
    'spawn': 'python -I work/scripts/write_manifest_k1.py',
    'status': None,
    'note': 'This process. The wrapper writes work/out/cmd/39.out, 39.err and 39.exit after the manifest is closed, so those three files are not entries above. work/out/cmd/39.cmd.txt is written before this process starts.',
})


def tool(cmd):
    try:
        return subprocess.check_output(cmd, text=True, stderr=subprocess.STDOUT).strip()
    except Exception as e:
        return str(e)


brief_sha, _ = sha_file('brief.md')
manifest = {
    'task': 'T5',
    'brief_sha256': brief_sha,
    'brief_hashed': 'later',
    'inputs': inputs,
    'sources': sources,
    'outputs': outputs,
    'commands': commands,
    'tool_versions': {'node26': tool(['node26', '--version']), 'python': tool(['python', '--version'])},
    'note': 'Execution hashes of emulator modules, including transitive static imports, were taken before the page-27 sessions and stored in work/out/import-inventory-k1.json. Session helper-hashes add the unpacked firmware and the session module at session start. later hashes were taken by this script. The manifest file itself is not an output entry. The profile byte is RAM only. No firmware image was written. Subject Detect stayed Off.',
}
Path('work/evidence-manifest.json').write_text(json.dumps(manifest, indent=2) + '\n', encoding='utf-8')
bad = [r['path'] for r in inputs + sources if r.get('later_matches') is False or r.get('conflicts')]
print('inputs', len(inputs), 'sources', len(sources), 'outputs', len(outputs), 'mismatches', bad)
